      es: ["Reserva desde 1995.", "Población de dugongos: aprox. 100 animales.", "Pastos marinos como alimento principal.", "Paseos en barco con reglas de distancia.", "Parte de un área marina protegida.", "Investigación sobre la ecología del dugongo."],
      pt: ["Reserva desde 1995.", "População de dugongos: aprox. 100 animais.", "Ervas marinhas como alimento principal.", "Passeios de barco com regras de distância.", "Parte de uma área marinha protegida.", "Pesquisa sobre a ecologia do dugongo."],
